import React from 'react';
import {
  Pressable,
  Text,
  ActivityIndicator,
  type ViewStyle,
  type GestureResponderEvent,
} from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { cn } from '../lib/utils';

type ButtonVariant = 'primary' | 'secondary' | 'ghost' | 'destructive' | 'text';
type ButtonSize = 'sm' | 'md' | 'lg';

interface ButtonProps {
  title: string;
  onPress: (e: GestureResponderEvent) => void;
  variant?: ButtonVariant;
  size?: ButtonSize;
  loading?: boolean;
  disabled?: boolean;
  fullWidth?: boolean;
  icon?: keyof typeof Ionicons.glyphMap;
  iconPosition?: 'left' | 'right';
  accessibilityLabel?: string;
  className?: string;
}

const variantStyles: Record<ButtonVariant, { container: string; text: string }> = {
  primary: {
    container: 'bg-accent',
    text: 'text-white',
  },
  secondary: {
    container: 'bg-transparent border border-borderStrong',
    text: 'text-textPrimary',
  },
  ghost: {
    container: 'bg-transparent',
    text: 'text-textSecondary',
  },
  destructive: {
    container: 'bg-error',
    text: 'text-white',
  },
  text: {
    container: 'bg-transparent',
    text: 'text-accent',
  },
};

const sizeStyles: Record<ButtonSize, { container: string; text: string; iconSize: number }> = {
  sm: { container: 'h-[36px] px-3 rounded-md', text: 'text-[13px]', iconSize: 16 },
  md: { container: 'h-[48px] px-5 rounded-lg', text: 'text-[15px]', iconSize: 18 },
  lg: { container: 'h-[56px] px-6 rounded-xl', text: 'text-[16px]', iconSize: 20 },
};

export function Button({
  title,
  onPress,
  variant = 'primary',
  size = 'md',
  loading = false,
  disabled = false,
  fullWidth = true,
  icon,
  iconPosition = 'left',
  accessibilityLabel,
  className,
}: ButtonProps) {
  const v = variantStyles[variant];
  const s = sizeStyles[size];
  const isDisabled = disabled || loading;

  return (
    <Pressable
      onPress={onPress}
      disabled={isDisabled}
      accessibilityLabel={accessibilityLabel ?? title}
      accessibilityRole="button"
      accessibilityState={{ disabled: isDisabled }}
      className={cn(
        'flex-row items-center justify-center',
        s.container,
        v.container,
        fullWidth ? 'w-full' : 'self-start',
        isDisabled && 'opacity-50',
        className,
      )}
      style={({ pressed }: { pressed: boolean }): ViewStyle => ({
        opacity: pressed && !isDisabled ? 0.92 : 1,
      })}
    >
      {loading ? (
        <ActivityIndicator
          size="small"
          color={variant === 'primary' || variant === 'destructive' ? '#FFFFFF' : '#6366F1'}
        />
      ) : (
        <>
          {icon && iconPosition === 'left' ? (
            <Ionicons
              name={icon}
              size={s.iconSize}
              color={variant === 'primary' || variant === 'destructive' ? '#FFFFFF' : '#A0A0A0'}
              style={{ marginRight: 8 }}
            />
          ) : null}
          <Text className={cn('font-semibold', s.text, v.text)}>
            {title}
          </Text>
          {icon && iconPosition === 'right' ? (
            <Ionicons
              name={icon}
              size={s.iconSize}
              color={variant === 'primary' || variant === 'destructive' ? '#FFFFFF' : '#A0A0A0'}
              style={{ marginLeft: 8 }}
            />
          ) : null}
        </>
      )}
    </Pressable>
  );
}

import React from 'react';
import { View, TextInput, Text, Pressable, type KeyboardTypeOptions } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { cn } from '../lib/utils';
import { colors } from '../lib/theme';

type InputVariant = 'standard' | 'password' | 'search' | 'currency';

interface InputProps {
  label?: string;
  value: string;
  onChangeText: (text: string) => void;
  placeholder?: string;
  error?: string;
  helperText?: string;
  variant?: InputVariant;
  leftIcon?: keyof typeof Ionicons.glyphMap;
  rightIcon?: keyof typeof Ionicons.glyphMap;
  onRightIconPress?: () => void;
  keyboardType?: KeyboardTypeOptions;
  autoFocus?: boolean;
  currencySymbol?: string;
  accessibilityLabel?: string;
  editable?: boolean;
  multiline?: boolean;
  numberOfLines?: number;
  className?: string;
}

export function Input({
  label,
  value,
  onChangeText,
  placeholder,
  error,
  helperText,
  variant = 'standard',
  leftIcon,
  rightIcon,
  onRightIconPress,
  keyboardType,
  autoFocus = false,
  currencySymbol = '$',
  accessibilityLabel,
  editable = true,
  multiline = false,
  numberOfLines,
  className,
}: InputProps) {
  const [focused, setFocused] = React.useState(false);
  const [passwordVisible, setPasswordVisible] = React.useState(false);

  const isPassword = variant === 'password';
  const isSearch = variant === 'search';
  const isCurrency = variant === 'currency';

  const resolvedSecure = isPassword ? !passwordVisible : undefined;
  const resolvedKeyboard: KeyboardTypeType =
    isCurrency ? 'numeric' : (keyboardType ?? 'default');

  const resolvedLeftIcon = (isSearch ? 'search-outline' : leftIcon) as keyof typeof Ionicons.glyphMap | undefined;
  const resolvedRightIcon = (isSearch ? 'camera-outline' : rightIcon) as keyof typeof Ionicons.glyphMap | undefined;

  function handleChangeText(text: string) {
    if (isCurrency) {
      const digits = text.replace(/\D/g, '');
      onChangeText(digits);
    } else {
      onChangeText(text);
    }
  }

  const baseContainer = isSearch
    ? 'h-[44px] rounded-full'
    : 'h-[52px] rounded-lg';

  const borderStyle = error
    ? 'border border-error'
    : focused
      ? 'border border-accent'
      : 'border border-border';

  return (
    <View className={cn('w-full', className)}>
      {label ? (
        <Text className="text-[14px] font-medium text-textSecondary mb-1.5">
          {label}
        </Text>
      ) : null}

      <View
        className={cn(
          'flex-row items-center px-4 bg-bgElevated',
          baseContainer,
          borderStyle,
        )}
      >
        {isCurrency ? (
          <Text className="text-[14px] text-textPrimary mr-1 font-medium">
            {currencySymbol}
          </Text>
        ) : null}

        {resolvedLeftIcon ? (
          <Ionicons
            name={resolvedLeftIcon}
            size={20}
            color={colors.textTertiary}
            style={{ marginRight: 8 }}
          />
        ) : null}

        <TextInput
          value={isCurrency ? value.replace(/\B(?=(\d{3})+(?!\d))/g, ',') : value}
          onChangeText={handleChangeText}
          placeholder={placeholder}
          placeholderTextColor={colors.textTertiary}
          secureTextEntry={resolvedSecure}
          keyboardType={resolvedKeyboard}
          autoFocus={autoFocus}
          editable={editable}
          multiline={multiline}
          numberOfLines={numberOfLines}
          onFocus={() => setFocused(true)}
          onBlur={() => setFocused(false)}
          accessibilityLabel={accessibilityLabel ?? label ?? placeholder}
          className="flex-1 text-[15px] text-textPrimary"
          style={{ outlineStyle: 'none' }}
        />

        {isPassword ? (
          <Pressable
            onPress={() => setPasswordVisible((p) => !p)}
            accessibilityLabel={passwordVisible ? 'Hide password' : 'Show password'}
            hitSlop={8}
          >
            <Ionicons
              name={passwordVisible ? 'eye-off-outline' : 'eye-outline'}
              size={22}
              color={colors.textTertiary}
            />
          </Pressable>
        ) : null}

        {!isPassword && resolvedRightIcon ? (
          <Pressable
            onPress={onRightIconPress}
            accessibilityLabel={`${String(resolvedRightIcon)} button`}
            hitSlop={8}
            disabled={!onRightIconPress}
          >
            <Ionicons
              name={resolvedRightIcon}
              size={22}
              color={colors.textTertiary}
            />
          </Pressable>
        ) : null}
      </View>

      {error ? (
        <Text className="text-error text-[12px] mt-1.5">{error}</Text>
      ) : null}
      {!error && helperText ? (
        <Text className="text-textTertiary text-[12px] mt-1.5">{helperText}</Text>
      ) : null}
    </View>
  );
}

import React from 'react';
import { View, Text } from 'react-native';
import { cn } from '../lib/utils';

type BadgeVariant = 'accent' | 'success' | 'warning' | 'error' | 'info' | 'neutral';

interface BadgeProps {
  label: string;
  variant?: BadgeVariant;
  className?: string;
}

const variantStyles: Record<BadgeVariant, { bg: string; text: string }> = {
  accent: { bg: 'bg-accent/15', text: 'text-accent' },
  success: { bg: 'bg-success/15', text: 'text-success' },
  warning: { bg: 'bg-warning/15', text: 'text-warning' },
  error: { bg: 'bg-error/15', text: 'text-error' },
  info: { bg: 'bg-info/15', text: 'text-info' },
  neutral: { bg: 'bg-bgHover', text: 'text-textSecondary' },
};

export function Badge({ label, variant = 'neutral', className }: BadgeProps) {
  const s = variantStyles[variant];

  return (
    <View className={cn('self-start px-2 py-0.5 rounded', s.bg, className)}>
      <Text className={cn('text-[11px] font-semibold', s.text)}>
        {label}
      </Text>
    </View>
  );
}

import React from 'react';
import { View, Text } from 'react-native';
import { Image } from 'expo-image';
import { cn } from '../lib/utils';

type AvatarSize = 'sm' | 'md' | 'lg' | 'xl';

interface AvatarProps {
  source?: string;
  name?: string;
  size?: AvatarSize;
  className?: string;
}

const sizeMap: Record<AvatarSize, { dim: number; text: string }> = {
  sm: { dim: 28, text: 'text-[11px]' },
  md: { dim: 36, text: 'text-[13px]' },
  lg: { dim: 48, text: 'text-[16px]' },
  xl: { dim: 64, text: 'text-[20px]' },
};

function getInitials(name?: string): string {
  if (!name) return '?';
  return name
    .split(' ')
    .map((n) => n[0])
    .join('')
    .toUpperCase()
    .slice(0, 2);
}

export function Avatar({ source, name, size = 'md', className }: AvatarProps) {
  const s = sizeMap[size];

  if (source) {
    return (
      <Image
        source={{ uri: source }}
        className={cn('rounded-full bg-bgHover', className)}
        style={{ width: s.dim, height: s.dim }}
        contentFit="cover"
        transition={200}
      />
    );
  }

  return (
    <View
      className={cn(
        'rounded-full bg-accent/20 items-center justify-center',
        className,
      )}
      style={{ width: s.dim, height: s.dim }}
    >
      <Text className={cn('font-semibold text-accent', s.text)}>
        {getInitials(name)}
      </Text>
    </View>
  );
}

import React from 'react';
import { View, type ViewProps } from 'react-native';
import { cn } from '../lib/utils';

interface CardProps extends ViewProps {
  children: React.ReactNode;
  className?: string;
}

export function Card({ children, className, style, ...props }: CardProps) {
  return (
    <View
      className={cn('rounded-xl bg-bgElevated border border-border', className)}
      style={style}
      {...props}
