import React from 'react';
import { View, ActivityIndicator, Text } from 'react-native';
import { cn } from '../lib/utils';

interface LoadingSpinnerProps {
  size?: 'small' | 'large';
  message?: string;
  fullScreen?: boolean;
  className?: string;
}

export function LoadingSpinner({
  size = 'large',
  message,
  fullScreen = false,
  className,
}: LoadingSpinnerProps) {
  const content = (
    <View className={cn('items-center justify-center', className)}>
      <ActivityIndicator size={size} color="#6366F1" />
      {message ? (
        <Text className="text-textSecondary text-[14px] mt-3">{message}</Text>
      ) : null}
    </View>
  );

  if (fullScreen) {
    return (
      <View className="flex-1 items-center justify-center bg-bg">
        {content}
      </View>
    );
  }

  return content;
}

import React, { useEffect, useRef } from 'react';
import { View, Text, Pressable, Animated } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { cn } from '../lib/utils';

type ToastType = 'success' | 'error' | 'warning' | 'info';

interface ToastAction {
  label: string;
  onPress: () => void;
}

interface ToastProps {
  visible: boolean;
  message: string;
  type?: ToastType;
  action?: ToastAction;
  onDismiss?: () => void;
  duration?: number;
  className?: string;
}

const typeConfig: Record<ToastType, { icon: keyof typeof Ionicons.glyphMap; bg: string; border: string }> = {
  success: { icon: 'checkmark-circle', bg: 'bg-successLight', border: 'border-success/30' },
  error: { icon: 'alert-circle', bg: 'bg-errorLight', border: 'border-error/30' },
  warning: { icon: 'warning', bg: 'bg-warningLight', border: 'border-warning/30' },
  info: { icon: 'information-circle', bg: 'bg-infoLight', border: 'border-info/30' },
};

export function Toast({
  visible,
  message,
  type = 'info',
  action,
  onDismiss,
  duration = 3000,
  className,
}: ToastProps) {
  const opacity = useRef(new Animated.Value(0)).current;
  const translateY = useRef(new Animated.Value(-20)).current;

  useEffect(() => {
    if (visible) {
      Animated.parallel([
        Animated.timing(opacity, { toValue: 1, duration: 200, useNativeDriver: true }),
        Animated.timing(translateY, { toValue: 0, duration: 200, useNativeDriver: true }),
      ]).start();

      const timer = setTimeout(() => {
        Animated.parallel([
          Animated.timing(opacity, { toValue: 0, duration: 200, useNativeDriver: true }),
          Animated.timing(translateY, { toValue: -20, duration: 200, useNativeDriver: true }),
        ]).start(() => onDismiss?.());
      }, duration);

      return () => clearTimeout(timer);
    }
  }, [visible]);

  if (!visible) return null;

  const cfg = typeConfig[type];

  return (
    <Animated.View
      className={cn(
        'absolute top-12 left-4 right-4 z-50 flex-row items-center rounded-xl border px-4 py-3',
        cfg.bg,
        cfg.border,
        className,
      )}
      style={{ opacity, transform: [{ translateY }] }}
    >
      <Ionicons name={cfg.icon} size={20} color={type === 'success' ? '#22C55E' : type === 'error' ? '#EF4444' : type === 'warning' ? '#F59E0B' : '#3B82F6'} />
      <Text className="flex-1 text-textPrimary text-[14px] ml-3">{message}</Text>
      {action ? (
        <Pressable onPress={action.onPress} className="ml-2">
          <Text className="text-accent text-[13px] font-semibold">{action.label}</Text>
        </Pressable>
      ) : null}
      {onDismiss ? (
        <Pressable onPress={onDismiss} className="ml-2" hitSlop={8}>
          <Ionicons name="close" size={18} color="#666666" />
        </Pressable>
      ) : null}
    </Animated.View>
  );
}

import React from 'react';
import { View, Pressable } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { cn } from '../lib/utils';

interface RatingProps {
  value: number;
  max?: number;
  size?: 'sm' | 'md' | 'lg';
  onChange?: (value: number) => void;
  disabled?: boolean;
  showEmpty?: boolean;
  className?: string;
}

const sizeMap = { sm: 14, md: 18, lg: 24 };

export function Rating({
  value,
  max = 5,
  size = 'md',
  onChange,
  disabled = true,
  showEmpty = true,
  className,
}: RatingProps) {
  const iconSize = sizeMap[size];
  const interactive = !disabled && !!onChange;

  return (
    <View className={cn('flex-row items-center gap-0.5', className)}>
      {Array.from({ length: max }, (_, i) => {
        const filled = i < Math.floor(value);
        const half = !filled && i < value;
        const starName = filled ? 'star' : half ? 'star-half' : showEmpty ? 'star-outline' : undefined;

        if (!starName) return null;

        return (
          <Pressable
            key={i}
            onPress={() => onChange?.(i + 1)}
            disabled={!interactive}
            className={interactive ? 'p-0.5' : ''}
          >
            <Ionicons
              name={starName as keyof typeof Ionicons.glyphMap}
              size={iconSize}
              color={filled || half ? '#F59E0B' : '#333333'}
            />
          </Pressable>
        );
      })}
    </View>
  );
}

import React from 'react';
import { Pressable, View, Text } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { cn } from '../lib/utils';

interface CustomRadioProps {
  selected: boolean;
  onSelect: () => void;
  label?: string;
  description?: string;
  disabled?: boolean;
  className?: string;
}

export function CustomRadio({
  selected,
  onSelect,
  label,
  description,
  disabled = false,
  className,
}: CustomRadioProps) {
  return (
    <Pressable
      onPress={onSelect}
      disabled={disabled}
      className={cn(
        'flex-row items-center gap-3 rounded-xl border px-4 py-3.5',
        selected
          ? 'border-accent bg-accent/5'
          : 'border-border bg-bgElevated',
        disabled && 'opacity-50',
        className,
      )}
    >
      <View
        className={cn(
          'w-5 h-5 rounded-full border-2 items-center justify-center',
          selected ? 'border-accent' : 'border-borderStrong',
        )}
      >
        {selected ? (
          <View className="w-2.5 h-2.5 rounded-full bg-accent" />
        ) : null}
      </View>
      {label ? (
        <View className="flex-1">
          <Text
            className={cn(
              'text-[15px] font-medium',
              selected ? 'text-textPrimary' : 'text-textSecondary',
            )}
          >
            {label}
          </Text>
          {description ? (
            <Text className="text-textTertiary text-[13px] mt-0.5">
              {description}
            </Text>
          ) : null}
        </View>
      ) : null}
    </Pressable>
  );
}

import React from 'react';
import { View } from 'react-native';
import { cn } from '../lib/utils';

interface DividerProps {
  className?: string;
}

export function Divider({ className }: DividerProps) {
  return <View className={cn('h-px bg-border', className)} />;
}

import React, { useEffect, useRef } from 'react';
import { View, Animated } from 'react-native';
import { cn } from '../lib/utils';

interface SkeletonProps {
  width?: number | string;
  height?: number | string;
  borderRadius?: number;
  className?: string;
}

export function Skeleton({
  width = '100%',
  height = 20,
  borderRadius = 8,
  className,
}: SkeletonProps) {
  const opacity = useRef(new Animated.Value(0.3)).current;

  useEffect(() => {
    const animation = Animated.loop(
      Animated.sequence([
        Animated.timing(opacity, { toValue: 0.6, duration: 800, useNativeDriver: true }),
        Animated.timing(opacity, { toValue: 0.3, duration: 800, useNativeDriver: true }),
      ]),
    );
    animation.start();
    return () => animation.stop();
  }, []);

  return (
    <Animated.View
      className={cn('bg-bgHover', className)}
      style={{ width, height, borderRadius, opacity }}
    />
  );
}

export function SkeletonCard({ className }: { className?: string }) {
  return (
    <View className={cn('rounded-xl bg-bgElevated border border-border p-4', className)}>
      <Skeleton height={160} borderRadius={8} />
      <View className="mt-3 gap-2">
        <Skeleton height={14} width="70%" />
        <Skeleton height={14} width="40%" />
        <Skeleton height={12} width="50%" />
      </View>
    </View>
  );
}

import React from 'react';
import {
  View,
  Text,
  TextInput,
  Pressable,
  FlatList,
  Modal,
} from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { cn } from '../lib/utils';
import { colors } from '../lib/theme';

interface SearchableSelectOption {
  label: string;
  value: string;
  description?: string;
}

interface SearchableSelectProps {
  options: SearchableSelectOption[];
  value?: string;
  onChange: (value: string) => void;
  placeholder?: string;
  label?: string;
  error?: string;
  disabled?: boolean;
  className?: string;
}

export function SearchableSelect({
  options,
  value,
  onChange,
  placeholder = 'Search...',
  label,
  error,
  disabled = false,
  className,
}: SearchableSelectProps) {
  const [open, setOpen] = React.useState(false);
  const [query, setQuery] = React.useState('');

  const selected = options.find((o) => o.value === value);
  const filtered = query.trim()
    ? options.filter(
        (o) =>
          o.label.toLowerCase().includes(query.toLowerCase()) ||
          o.description?.toLowerCase().includes(query.toLowerCase()),
      )
    : options;

  return (
    <View className={cn('w-full', className)}>
      {label ? (
        <Text className="text-[14px] font-medium text-textSecondary mb-1.5">
          {label}
        </Text>
      ) : null}

      <Pressable
        onPress={() => { if (!disabled) { setOpen(true); setQuery(''); } }}
        disabled={disabled}
        className="flex-row items-center h-[52px] rounded-lg border border-border bg-bgElevated px-4"
      >
        <Text
          className={`flex-1 text-[15px] ${
            selected ? 'text-textPrimary' : 'text-textTertiary'
          }`}
        >
          {selected ? selected.label : placeholder}
        </Text>
        <Ionicons name="chevron-down" size={18} color={colors.textTertiary} />
      </Pressable>

      {error ? (
        <Text className="text-error text-[12px] mt-1.5">{error}</Text>
      ) : null}

      <Modal visible={open} transparent animationType="slide">
        <Pressable
          className="flex-1"
          style={{ backgroundColor: 'rgba(0,0,0,0.6)' }}
          onPress={() => setOpen(false)}
        />
        <View className="bg-bgElevated rounded-t-2xl max-h-[60%] pb-8">
          <View className="items-center pt-2 pb-3">
            <View className="w-9 h-1 rounded-full bg-borderStrong" />
          </View>
          <View className="px-4 pb-3">
            <View className="flex-row items-center h-[44px] rounded-full bg-bgSubtle px-4">
              <Ionicons name="search" size={18} color={colors.textTertiary} />
              <TextInput
                value={query}
                onChangeText={setQuery}
                placeholder={placeholder}
                placeholderTextColor={colors.textTertiary}
                className="flex-1 text-[15px] text-textPrimary ml-2"
                autoFocus
              />
              {query ? (
                <Pressable onPress={() => setQuery('')} hitSlop={8}>
                  <Ionicons name="close" size={18} color={colors.textTertiary} />
                </Pressable>
              ) : null}
            </View>
          </View>
          <FlatList
            data={filtered}
            keyExtractor={(item) => item.value}
            contentContainerStyle={{ paddingHorizontal: 16 }}
            renderItem={({ item }) => (
              <Pressable
                onPress={() => {
                  onChange(item.value);
                  setOpen(false);
                }}
                className={`rounded-xl px-4 py-3.5 mb-1 ${
                  item.value === value
                    ? 'bg-accent/10 border border-accent/30'
                    : 'bg-bgSubtle'
                }`}
              >
                <Text className="text-[15px] font-medium text-textPrimary">
                  {item.label}
                </Text>
                {item.description ? (
                  <Text className="text-textTertiary text-[13px] mt-0.5">
                    {item.description}
                  </Text>
                ) : null}
              </Pressable>
            )}
            ListEmptyComponent={
              <Text className="text-textTertiary text-[14px] text-center py-8">
                No results found
              </Text>
            }
          />
        </View>
      </Modal>
    </View>
  );
}

import React from 'react';
import { View, Text } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { cn } from '../lib/utils';

interface CountdownTimerProps {
  hours: number;
  minutes: number;
  seconds: number;
  label?: string;
  size?: 'sm' | 'md' | 'lg';
  className?: string;
}

const sizeMap = {
  sm: { box: 'w-8 h-8', text: 'text-[13px]', gap: 1, icon: 14 },
  md: { box: 'w-10 h-10', text: 'text-[16px]', gap: 2, icon: 16 },
  lg: { box: 'w-14 h-14', text: 'text-[22px]', gap: 3, icon: 18 },
};

export function CountdownTimer({
  hours,
  minutes,
  seconds,
  label,
  size = 'md',
  className,
}: CountdownTimerProps) {
  const s = sizeMap[size];

  function pad(n: number): string {
    return n.toString().padStart(2, '0');
  }

  return (
    <View className={cn('items-center', className)}>
      {label ? (
        <Text className="text-textSecondary text-[12px] font-medium mb-2">
          {label}
        </Text>
      ) : null}
      <View className="flex-row items-center gap-1">
        <View
          className={cn(
            'rounded-lg bg-bgHover items-center justify-center',
            s.box,
          )}
        >
          <Text className={cn('font-bold text-textPrimary tabular-nums', s.text)}>
            {pad(hours)}
          </Text>
        </View>
        <Text className={cn('font-bold text-textTertiary', s.text)}>:</Text>
        <View
          className={cn(
            'rounded-lg bg-bgHover items-center justify-center',
            s.box,
          )}
        >
          <Text className={cn('font-bold text-textPrimary tabular-nums', s.text)}>
            {pad(minutes)}
          </Text>
        </View>
        <Text className={cn('font-bold text-textTertiary', s.text)}>:</Text>
        <View
          className={cn(
            'rounded-lg bg-bgHover items-center justify-center',
            s.box,
          )}
        >
          <Text className={cn('font-bold text-textPrimary tabular-nums', s.text)}>
            {pad(seconds)}
          </Text>
        </View>
      </View>
    </View>
  );
}

import React, { useMemo } from 'react';
import { View, Text } from 'react-native';

interface OTPInputProps {
  code: string;
  length?: number;
  error?: boolean;
  className?: string;
}

export function OTPInput({
  code,
  length = 4,
  error = false,
  className,
}: OTPInputProps) {
  const boxes = useMemo(
    () => Array.from({ length }, (_, i) => code[i] ?? ''),
    [code, length],
  );

  return (
    <View className={`flex-row justify-center gap-3 ${className ?? ''}`}>
      {boxes.map((digit, i) => (
        <View
          key={i}
          className={`w-[56px] h-[64px] rounded-xl border-2 items-center justify-center ${
            error
              ? 'border-error bg-error/10'
              : digit
                ? 'border-accent bg-accent/10'
                : 'border-border bg-bgElevated'
          }`}
        >
          <Text className="text-[24px] font-bold text-textPrimary">
            {digit}
          </Text>
        </View>
      ))}
    </View>
  );
}

import React from 'react';
import { Pressable, View, Text, Dimensions } from 'react-native';
import { Image } from 'expo-image';
import { Ionicons } from '@expo/vector-icons';
import { cn } from '../lib/utils';
import { Rating } from '../ui/rating';
import { Badge } from '../ui/badge';

export interface Product {
  id: string;
  name: string;
  price: number;
  compareAt?: number;
  image?: string;
  rating?: number;
  reviewCount?: number;
  badge?: string;
  currency?: string;
}

interface ProductCardProps {
  product: Product;
  onPress: () => void;
  onAddToCart?: () => void;
  onWishlistToggle?: () => void;
  isWishlisted?: boolean;
  className?: string;
  compact?: boolean;
}

const SCREEN_WIDTH = Dimensions.get('window').width;
const CARD_GAP = 12;
const CARD_WIDTH = (SCREEN_WIDTH - 16 * 2 - CARD_GAP) / 2;

export function ProductCard({
  product,
  onPress,
  onAddToCart,
  onWishlistToggle,
  isWishlisted = false,
  className,
  compact = false,
}: ProductCardProps) {
  const hasDiscount = product.compareAt && product.compareAt > product.price;
  const discount = hasDiscount
    ? Math.round((1 - product.price / product.compareAt!) * 100)
    : 0;

  const fmtPrice = (amount: number) =>
    new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: product.currency || 'USD',
      currencyDisplay: 'narrowSymbol',
    }).format(amount);

  return (
    <Pressable
      onPress={onPress}
      className={cn(
        'rounded-xl bg-bgElevated border border-border overflow-hidden',
        compact ? 'flex-row' : 'w-full',
        className,
      )}
      style={compact ? undefined : { width: CARD_WIDTH }}
    >
      <View className={compact ? 'w-[100px] h-[100px]' : 'relative'}>
        {product.image ? (
          <Image
            source={{ uri: product.image }}
            className={compact ? 'w-full h-full' : 'w-full aspect-square'}
            contentFit="cover"
            transition={200}
          />
        ) : (
          <View className={cn('bg-bgHover items-center justify-center', compact ? 'w-full h-full' : 'aspect-square')}>
            <Ionicons name="image-outline" size={28} color="#444444" />
          </View>
        )}

        {/* Wishlist */}
        {onWishlistToggle ? (
          <Pressable
            onPress={onWishlistToggle}
            className="absolute top-2 right-2 w-8 h-8 rounded-full bg-bg/80 items-center justify-center"
            hitSlop={6}
          >
            <Ionicons
              name={isWishlisted ? 'heart' : 'heart-outline'}
              size={16}
              color={isWishlisted ? '#EF4444' : '#A0A0A0'}
            />
          </Pressable>
        ) : null}

        {/* Discount badge */}
        {hasDiscount ? (
          <View className="absolute top-2 left-2 bg-error rounded px-1.5 py-0.5">
            <Text className="text-white text-[10px] font-bold">-{discount}%</Text>
          </View>
        ) : null}

        {/* Product badge */}
        {product.badge ? (
          <View className="absolute top-2 left-2 mt-7">
            <Badge label={product.badge} variant="accent" />
          </View>
        ) : null}
      </View>

      <View className={cn('flex-1', compact ? 'p-3 justify-center' : 'p-3')}>
        <Text
          className="text-[13px] font-semibold text-textPrimary"
          numberOfLines={2}
        >
          {product.name}
        </Text>

        <View className="flex-row items-center mt-1">
          <Text className="text-[16px] font-bold text-textPrimary tabular-nums">
            {fmtPrice(product.price)}
          </Text>
          {hasDiscount ? (
            <Text className="text-[12px] text-textTertiary line-through ml-2 tabular-nums">
              {fmtPrice(product.compareAt!)}
            </Text>
          ) : null}
        </View>

        {product.rating != null ? (
          <View className="flex-row items-center mt-1">
            <Rating value={product.rating} size="sm" />
            <Text className="text-textTertiary text-[11px] ml-1">
              {product.rating}
            </Text>
            {product.reviewCount != null ? (
              <Text className="text-textTertiary text-[11px] ml-1">
                ({product.reviewCount})
              </Text>
            ) : null}
          </View>
        ) : null}

        {onAddToCart && !compact ? (
          <Pressable
            onPress={onAddToCart}
            className="mt-2 h-[32px] rounded-lg bg-accent items-center justify-center"
          >
            <Text className="text-white text-[12px] font-semibold">Add to Cart</Text>
          </Pressable>
        ) : null}
      </View>
    </Pressable>
  );
}

export function ProductCardList({ product, onPress, onAddToCart }: {
  product: Product;
  onPress: () => void;
  onAddToCart?: () => void;
}) {
  return (
    <ProductCard
      product={product}
      onPress={onPress}
      onAddToCart={onAddToCart}
      compact
      className="w-full"
    />
  );
}

import React from 'react';
import { View, Text, Pressable } from 'react-native';
import { Image } from 'expo-image';
import { Ionicons } from '@expo/vector-icons';
import { cn } from '../lib/utils';

export interface CartItemData {
  productId: string;
  name: string;
  image: string;
  price: number;
  compareAt?: number;
  quantity: number;
  options?: Record<string, string>;
}

interface CartItemProps {
  item: CartItemData;
  onRemove: () => void;
  onUpdateQuantity: (qty: number) => void;
  onPress?: () => void;
  className?: string;
}

export function CartItem({
  item,
  onRemove,
  onUpdateQuantity,
  onPress,
  className,
}: CartItemProps) {
  const fmtPrice = (amount: number) =>
    new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      currencyDisplay: 'narrowSymbol',
    }).format(amount);

  return (
    <Pressable
      onPress={onPress}
      className={cn('flex-row p-4 border-b border-border', className)}
    >
      <View className="w-[90px] h-[90px] rounded-xl overflow-hidden bg-bgHover">
        <Image
          source={{ uri: item.image }}
          className="w-full h-full"
          contentFit="cover"
          transition={200}
        />
      </View>

      <View className="flex-1 ml-3">
        <Text className="text-[14px] font-semibold text-textPrimary" numberOfLines={2}>
          {item.name}
        </Text>

        {item.options && Object.entries(item.options).length > 0 ? (
          <Text className="text-textTertiary text-[12px] mt-0.5">
            {Object.entries(item.options)
              .map(([k, v]) => `${k}: ${v}`)
              .join(' · ')}
          </Text>
        ) : null}

        <View className="flex-row items-center mt-1">
          <Text className="text-[16px] font-bold text-textPrimary tabular-nums">
            {fmtPrice(item.price)}
          </Text>
          {item.compareAt && item.compareAt > item.price ? (
            <Text className="text-textTertiary text-[12px] line-through ml-2 tabular-nums">
              {fmtPrice(item.compareAt)}
            </Text>
          ) : null}
        </View>

        <View className="flex-row items-center justify-between mt-2">
          <View className="flex-row items-center">
            <Pressable
              onPress={() => item.quantity > 1 && onUpdateQuantity(item.quantity - 1)}
              className="w-7 h-7 rounded border border-border items-center justify-center"
            >
              <Text className="text-textPrimary text-[15px] font-medium">-</Text>
            </Pressable>
            <View className="w-7 h-7 border-y border-border items-center justify-center">
              <Text className="text-textPrimary text-[13px] font-semibold">
                {item.quantity}
              </Text>
            </View>
            <Pressable
              onPress={() => onUpdateQuantity(item.quantity + 1)}
              className="w-7 h-7 rounded border border-border items-center justify-center"
            >
              <Text className="text-textPrimary text-[15px] font-medium">+</Text>
            </Pressable>
          </View>

          <Pressable onPress={onRemove} hitSlop={8}>
            <Ionicons name="trash-outline" size={18} color="#EF4444" />
          </Pressable>
        </View>
      </View>
    </Pressable>
  );
}

import React from 'react';
import { View, Text } from 'react-native';
import { cn } from '../lib/utils';

interface PriceDisplayProps {
  price: number;
  compareAt?: number;
  currency?: string;
  size?: 'sm' | 'md' | 'lg';
  showDiscount?: boolean;
  className?: string;
}

export function PriceDisplay({
  price,
  compareAt,
  currency = 'USD',
  size = 'md',
  showDiscount = true,
  className,
}: PriceDisplayProps) {
  const fmt = (amount: number) =>
    new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency,
      currencyDisplay: 'narrowSymbol',
    }).format(amount);

  const discount =
    compareAt && compareAt > price
      ? Math.round((1 - price / compareAt) * 100)
      : 0;

  const sizeMap = {
    sm: { price: 'text-[14px]', struck: 'text-[11px]', badge: 'text-[10px]' },
    md: { price: 'text-[18px]', struck: 'text-[13px]', badge: 'text-[11px]' },
    lg: { price: 'text-[24px]', struck: 'text-[16px]', badge: 'text-[12px]' },
  };

  const s = sizeMap[size];

  return (
    <View className={cn('flex-row items-baseline gap-2', className)}>
      <Text className={cn('font-bold text-textPrimary tabular-nums', s.price)}>
        {fmt(price)}
      </Text>
      {compareAt && compareAt > price ? (
        <>
          <Text className={cn('text-textTertiary line-through tabular-nums', s.struck)}>
            {fmt(compareAt)}
          </Text>
          {showDiscount ? (
            <View className="bg-error/20 px-1.5 py-0.5 rounded">
              <Text className={cn('font-semibold text-error', s.badge)}>
                -{discount}%
              </Text>
            </View>
          ) : null}
        </>
      ) : null}
    </View>
  );
}

import React from 'react';
import { View, Text, Pressable } from 'react-native';
import { Image } from 'expo-image';
import { Ionicons } from '@expo/vector-icons';
import { cn } from '../lib/utils';
import { Badge } from '../ui/badge';

type OrderStatus = 'confirmed' | 'processing' | 'shipped' | 'delivered' | 'cancelled' | 'returned';

export interface Order {
  id: string;
  number: string;
  date: string;
  status: OrderStatus;
  total: number;
  items: { name: string; image: string; quantity: number }[];
}

interface OrderCardProps {
  order: Order;
  onPress: () => void;
  onTrack?: () => void;
  className?: string;
}

const statusConfig: Record<OrderStatus, { label: string; variant: 'success' | 'warning' | 'info' | 'error' | 'neutral' }> = {
  confirmed: { label: 'Confirmed', variant: 'info' },
  processing: { label: 'Processing', variant: 'warning' },
  shipped: { label: 'Shipped', variant: 'accent' },
  delivered: { label: 'Delivered', variant: 'success' },
  cancelled: { label: 'Cancelled', variant: 'error' },
  returned: { label: 'Returned', variant: 'neutral' },
};

export function OrderCard({ order, onPress, onTrack, className }: OrderCardProps) {
  const cfg = statusConfig[order.status];
  const fmtPrice = (amount: number) =>
    new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
    }).format(amount);

  return (
    <Pressable
      onPress={onPress}
      className={cn('rounded-xl border border-border bg-bgElevated overflow-hidden', className)}
    >
      <View className="flex-row items-center justify-between px-4 py-3 border-b border-border">
        <View>
          <Text className="text-[13px] font-semibold text-textPrimary">{order.number}</Text>
          <Text className="text-textTertiary text-[12px] mt-0.5">{order.date}</Text>
        </View>
        <Badge label={cfg.label} variant={cfg.variant} />
      </View>

      <View className="px-4 py-3">
        <View className="flex-row gap-2">
          {order.items.slice(0, 3).map((item, i) => (
            <View key={i} className="w-14 h-14 rounded-lg overflow-hidden bg-bgHover">
              <Image source={{ uri: item.image }} className="w-full h-full" contentFit="cover" />
            </View>
          ))}
          {order.items.length > 3 ? (
            <View className="w-14 h-14 rounded-lg bg-bgSubtle items-center justify-center">
              <Text className="text-textSecondary text-[11px] font-medium">
                +{order.items.length - 3}
              </Text>
            </View>
          ) : null}
        </View>
      </View>

      <View className="flex-row items-center justify-between px-4 py-3 border-t border-border">
        <Text className="text-[15px] font-bold text-textPrimary tabular-nums">
          {fmtPrice(order.total)}
        </Text>
        {onTrack && order.status !== 'delivered' && order.status !== 'cancelled' ? (
          <Pressable onPress={onTrack} className="flex-row items-center gap-1">
            <Text className="text-accent text-[13px] font-semibold">Track</Text>
            <Ionicons name="chevron-forward" size={14} color="#6366F1" />
          </Pressable>
        ) : null}
      </View>
    </Pressable>
  );
}

import React from 'react';
import { View, Text } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { cn } from '../lib/utils';

type OrderTimelineStep = {
  label: string;
  date?: string;
  completed: boolean;
  active: boolean;
};

interface OrderTimelineProps {
  steps: OrderTimelineStep[];
  className?: string;
}

export function OrderTimeline({ steps, className }: OrderTimelineProps) {
  return (
    <View className={cn('px-4 py-2', className)}>
      {steps.map((step, i) => (
        <View key={i} className="flex-row">
          {/* Timeline */}
          <View className="items-center w-8">
            <View
              className={cn(
                'w-7 h-7 rounded-full items-center justify-center',
                step.active
                  ? 'bg-accent'
                  : step.completed
                    ? 'bg-success'
                    : 'bg-bgHover',
              )}
            >
              {step.completed || step.active ? (
                <Ionicons name="checkmark" size={16} color="#FFFFFF" />
              ) : (
                <View className="w-2 h-2 rounded-full bg-borderStrong" />
              )}
            </View>
            {i < steps.length - 1 ? (
              <View
                className={cn(
                  'w-0.5 flex-1',
                  step.completed ? 'bg-success' : 'bg-border',
                )}
                style={{ minHeight: 24 }}
              />
            ) : null}
          </View>

          {/* Content */}
          <View className={cn('flex-1 ml-3', i < steps.length - 1 && 'pb-4')}>
            <Text
              className={cn(
                'text-[14px]',
                step.active
                  ? 'font-semibold text-textPrimary'
                  : step.completed
                    ? 'text-textPrimary'
                    : 'text-textTertiary',
              )}
            >
              {step.label}
            </Text>
            {step.date ? (
              <Text className="text-textTertiary text-[12px] mt-0.5">
                {step.date}
              </Text>
            ) : null}
          </View>
        </View>
      ))}
    </View>
  );
}

import React from 'react';
import { View, Text, Pressable, ScrollView } from 'react-native';
import { Image } from 'expo-image';
import { Ionicons } from '@expo/vector-icons';
import { cn } from '../lib/utils';
import { Badge } from '../ui/badge';
import { Rating } from '../ui/rating';
import { Divider } from '../ui/divider';

export interface ProductDetailData {
  id: string;
  name: string;
  price: number;
  compareAt?: number;
  description?: string;
  images: string[];
  rating?: number;
  reviewCount?: number;
  colors?: { name: string; hex: string }[];
  sizes?: string[];
  badge?: string;
}

interface ProductHeaderProps {
  product: ProductDetailData;
  selectedColor?: string;
  selectedSize?: string;
  onColorChange?: (color: string) => void;
  onSizeChange?: (size: string) => void;
  onAddToCart?: () => void;
  onWishlistToggle?: () => void;
  isWishlisted?: boolean;
  className?: string;
}

export function ProductHeader({
  product,
  selectedColor,
  selectedSize,
  onColorChange,
  onSizeChange,
  onAddToCart,
  onWishlistToggle,
  isWishlisted = false,
  className,
}: ProductHeaderProps) {
  const fmtPrice = (amount: number) =>
    new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', currencyDisplay: 'narrowSymbol' }).format(amount);

  return (
    <ScrollView className={cn('flex-1 bg-bg', className)}>
      {/* Image gallery */}
      <ScrollView horizontal pagingEnabled showsHorizontalScrollIndicator={false}>
        {product.images.map((img, i) => (
          <View key={i} className="w-screen aspect-[3/4] bg-bgHover">
            <Image source={{ uri: img }} className="w-full h-full" contentFit="cover" />
          </View>
        ))}
      </ScrollView>

      <View className="px-4 pt-4 pb-6">
        {/* Badge + wishlist */}
        <View className="flex-row items-center justify-between">
          {product.badge ? <Badge label={product.badge} variant="accent" /> : <View />}
          {onWishlistToggle ? (
            <Pressable onPress={onWishlistToggle} hitSlop={8}>
              <Ionicons name={isWishlisted ? 'heart' : 'heart-outline'} size={22} color={isWishlisted ? '#EF4444' : '#A0A0A0'} />
            </Pressable>
          ) : null}
        </View>

        {/* Name */}
        <Text className="text-[18px] font-semibold text-textPrimary mt-2">{product.name}</Text>

        {/* Price */}
        <View className="flex-row items-baseline gap-2 mt-1">
          <Text className="text-[22px] font-bold text-textPrimary tabular-nums">{fmtPrice(product.price)}</Text>
          {product.compareAt ? (
            <Text className="text-textTertiary text-[15px] line-through tabular-nums">{fmtPrice(product.compareAt)}</Text>
          ) : null}
        </View>

        {/* Rating */}
        {product.rating ? (
          <View className="flex-row items-center mt-2">
            <Rating value={product.rating} size="sm" />
            <Text className="text-textSecondary text-[13px] ml-2">
              {product.rating} ({product.reviewCount ?? 0} reviews)
            </Text>
          </View>
        ) : null}

        <Divider className="my-4" />

        {/* Color selector */}
        {product.colors && product.colors.length > 0 ? (
          <View className="mb-4">
            <Text className="text-[14px] font-semibold text-textPrimary mb-2">
              Color: {selectedColor ?? 'Select'}
            </Text>
            <View className="flex-row gap-3">
              {product.colors.map((c) => (
                <Pressable
                  key={c.name}
                  onPress={() => onColorChange?.(c.name)}
                  className={cn(
                    'w-8 h-8 rounded-full border-2',
                    selectedColor === c.name ? 'border-accent' : 'border-border',
                  )}
                  style={{ backgroundColor: c.hex }}
                />
              ))}
            </View>
          </View>
        ) : null}

        {/* Size selector */}
        {product.sizes && product.sizes.length > 0 ? (
          <View className="mb-4">
            <Text className="text-[14px] font-semibold text-textPrimary mb-2">
